 use fs2::FileExt;
 use gpui_kit::component::TitleBar;
 use gpui_kit::*;
+
+/// Keep the application content separate from Kit's window-layer dialogs.
+/// A dialog input's caret invalidates its own ancestors, not this sibling;
+/// reuse the unchanged content until Proxy notifies or its bounds change.
+/// Inputs inside Proxy still invalidate the cached ancestor normally.
+struct WindowContent {
+    proxy: Entity<ui::Proxy>,
+}
+
+impl Render for WindowContent {
+    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
+        self.proxy
+            .clone()
+            .cached(StyleRefinement::default().size_full())
+    }
+}
 pub(crate) fn default_window_size() -> Size<Pixels> {
     size(px(1440.), px(900.))
 }
